<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { api } from '../api';
import { dateText, errorText } from '../saas';
import ProvincePageState from './ProvincePageState.vue';
const props=defineProps<{modelValue:boolean;kind:string;row:any}>();const emit=defineEmits<{ 'update:modelValue':[value:boolean] }>();
const loading=ref(false),error=ref(''),detail=ref<any>(null);let generation=0;
const labels:Record<string,string>={ENTERPRISE:'企业档案',VEHICLE:'车辆档案',LICENSE:'通行许可',ALERT:'风险事件',ACCIDENT:'事故记录',VIOLATION:'违规记录'};
const statuses:Record<string,string>={ACTIVE:'有效',INACTIVE:'已停用',VALID:'有效',EXPIRED:'已到期',SUSPENDED:'已暂停',CANCELLED:'已注销',PENDING_CONFIRMATION:'待确认',PROCESSING:'处理中',PENDING_REVIEW:'待复核',CLOSED:'已闭环',REPORTED:'已上报',ARCHIVED:'已归档',RECTIFYING:'整改中',CONFIRMED:'已认定',PENDING_DETERMINATION:'待认定',ONLINE:'在线',OFFLINE:'离线'};
const entity=computed(()=>{const d=detail.value??props.row??{};return props.kind==='ENTERPRISE'?(d.enterprise??d):props.kind==='VEHICLE'?(d.vehicle??d):d});
const fields=computed(()=>{const d=detail.value??props.row??{};const e=entity.value;const entries:Array<[string,any]>=[['业务编号',d.businessNo??e.businessNo],['名称',e.name??d.title??d.licenseNo],['状态',statuses[d.status??e.status]??d.status??e.status],['所属企业',d.enterprise?.name??(props.kind==='ENTERPRISE'?e.name:undefined)],['所属机构',d.organization?.name??e.organization?.name]];if(props.kind==='ENTERPRISE')entries.push(['统一社会信用代码',e.creditCode],['法定代表人',e.legalRepresentative],['联系人',e.contactName],['联系电话',e.contactPhone],['注册地址',e.registeredAddress]);if(props.kind==='VEHICLE')entries.push(['统一编码',e.unifiedCode],['VIN',e.vin],['设备编号',e.deviceNo],['厂商车型',e.model?.name],['在线状态',statuses[e.onlineStatus]??e.onlineStatus]);if(props.kind==='LICENSE')entries.push(['牌照编号',d.licenseNo],['车辆',d.vehicle?.name??d.vehicle?.businessNo],['签发时间',dateText(d.issuedAt)],['有效期至',dateText(d.expiresAt)]);if(['ALERT','ACCIDENT','VIOLATION'].includes(props.kind))entries.push(['发生时间',dateText(d.occurredAt)],['车辆',d.vehicle?.businessNo??d.vehicle?.name],['发生地点',d.address],['事件描述',d.description],['最近处理',d.lastComment??d.disposalProgress??d.reviewComment]);return entries.filter(([,v])=>v!==undefined&&v!==null&&v!=='');});
const licenses=computed(()=>detail.value?.licenses??entity.value?.licenses??[]);const qualifications=computed(()=>detail.value?.qualifications??entity.value?.qualifications??[]);
async function load(){if(!props.row||!props.modelValue)return;const current=++generation;detail.value=props.row;error.value='';const endpoint=({ENTERPRISE:'/archives/enterprises/',VEHICLE:'/archives/vehicles/',ALERT:'/safety/alerts/',ACCIDENT:'/safety/accidents/',VIOLATION:'/safety/violations/'} as Record<string,string>)[props.kind];if(!endpoint)return;loading.value=true;try{const d=await api<any>(endpoint+props.row.id);if(current===generation)detail.value=d}catch(e){if(current===generation)error.value=errorText(e)}finally{if(current===generation)loading.value=false}}
watch(()=>[props.modelValue,props.row?.id,props.kind],load);
</script>
<template><el-drawer class="province-drawer" :model-value="modelValue" :title="labels[kind]??'对象详情'" size="650px" @update:model-value="emit('update:modelValue',$event)"><ProvincePageState :error="error" :loading="loading" @retry="load"><el-descriptions :column="1" border><el-descriptions-item v-for="[label,value] in fields" :key="label" :label="label">{{value}}</el-descriptions-item></el-descriptions><div v-if="licenses.length" class="province-detail-block" style="margin-top:22px"><h3>关联许可</h3><el-table :data="licenses"><el-table-column label="许可编号" prop="licenseNo"/><el-table-column label="有效期至"><template #default="{row}">{{dateText(row.expiresAt)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{statuses[row.status]??row.status}}</template></el-table-column></el-table></div><div v-if="qualifications.length" class="province-detail-block" style="margin-top:22px"><h3>资质材料</h3><el-table :data="qualifications"><el-table-column label="证书编号" prop="certificateNo"/><el-table-column label="签发单位" prop="issuedBy"/><el-table-column label="有效期至"><template #default="{row}">{{dateText(row.expiresAt)}}</template></el-table-column></el-table></div></ProvincePageState></el-drawer></template>
